//*****************************************************************************
//
// File Name        : 'Chlazeni_CHANGERs'
// Title            : Cooling of Changers in the Rack
// Author           : http://www.prochazka.zde.cz
// Created          : 21-10-2023, 11:00
// Revised          : 14-12-2025, 13:00
// Version          : 1.9
// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Tento skript řídí chlazení měničů (CHANGERs) v racku na základě těchto podmínek:
//
// CHLAZENÍ SE ZAPNE (sTurn = "on") když:
// 1. Baterie se vybíjí více než -600W (n_trigger_Changer)
//    Příklad: Baterie -650W → Chlazení ON (měnič aktivní, vybíjí baterii)
//
// 2. MPPT produkuje více než 600W (n_trigger_MPPT) A zároveň baterie 
//    se nenabíjí dostatečně (méně než +600W)
//    Příklad: MPPT 1500W, Baterie +200W → Chlazení ON (energie jde do gridu přes měnič)
//    Příklad: MPPT 800W, Baterie -100W → Chlazení ON (část z MPPT, část z baterie)
//
// CHLAZENÍ SE VYPNE (sTurn = "off") když:
// - MPPT nabíjí baterii (MPPT > 600W a Baterie nabíjí > +600W)
//   Příklad: MPPT 1500W, Baterie +800W → Chlazení OFF (MPPT jde hlavně do baterie)
// - Nízká produkce MPPT (MPPT < 600W) a baterie se nevybíjí moc
//   Příklad: MPPT 200W, Baterie +100W → Chlazení OFF
// - Hodnoty pod triggerem
//   Příklad: Baterie -500W → Chlazení OFF (nevybíjí se dost)
//
// NASTAVENÍ:
// - n_trigger_Changer = 600W (trigger pro vybíjení baterie)
// - n_trigger_MPPT = 600W (trigger pro produkci MPPT)
// - debug = true/false (zapne/vypne debug zprávy v konzoli)
//
// VSTUPNÍ DATA:
// - msg.payload._general_stop (true/false) - nouzové vypnutí
// - global.get("pvPower") - aktuální výkon MPPT v W
// - global.get("nBattery_Power") - aktuální výkon baterie v W (záporné=vybíjení, kladné=nabíjení)
//
// VÝSTUPNÍ DATA:
// - msg.payload._url_ch - URL pro ovládání relé
// - msg.payload.sTurn - stav chlazení ("on CHANGER" / "off CHANGER")
// - msg.payload.nTurn - binární stav (1/0)
// - msg.payload.pvPower - hodnota MPPT
// - msg.payload.nBattery_Power - hodnota baterie
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2025 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = true;  // Nastavte na true pro zapnutí debug zpráv

//definice globalních funkci
const fSendUrl = global.get('fSendUrl');
const nConvertSignetUnsignet = global.get('nConvertSignetUnsignet');

if (fSendUrl && nConvertSignetUnsignet) {

    const nRelayNumber = 0;
    const sIpAddress = "192.168.11.9";
    let sTurn = "off";  // Výchozí hodnota
    let nTurn = 0;  // Výchozí hodnota
    let n_trigger_Changer = 600; // defaultní hodnota triggeru pro baterii
    let n_trigger_MPPT = 600;    // defaultní hodnota triggeru pro MPPT
    let _url = "";
    let sStatusText = "";        // Text pro zobrazení pod nodem

    //Načtení vstupních dat
    const _general_stop = msg.payload._general_stop;// general stop

    // Načteni MPPT
    const pvPower = global.get("pvPower") || 0; // Hodnota z registru 819 

    // Nacteni baterie
    let nBattery_Power = global.get("nBattery_Power") || 0;

    if (_general_stop == true) {
        sTurn = "off";
        nTurn = 0;
        sStatusText = "General STOP aktivní";
    } else {
        // Logika pro zapnutí chlazení měniče
        let bCooling = false;

        // Podmínka 1: Baterie se vybíjí nad trigger
        if (nBattery_Power < -n_trigger_Changer) {
            bCooling = true;
            sStatusText = "ZAPNUTO - Baterie vybíjí: " + nBattery_Power + "W";
        }

        // Podmínka 2: MPPT produkuje nad trigger A baterie se dostatečně nenabíjí
        // (pokud by se baterie nabíjela hodně, znamená to že MPPT jde hlavně do baterie)
        else if (pvPower > n_trigger_MPPT && nBattery_Power < n_trigger_Changer) {
            bCooling = true;
            sStatusText = "ZAPNUTO - MPPT: " + pvPower + "W, Bat: " + nBattery_Power + "W";
        }

        // Nastavení výstupu podle podmínek
        if (bCooling) {
            sTurn = "on";
            nTurn = 1;
        } else {
            sTurn = "off";
            nTurn = 0;
            // Upřesněný důvod pro vypnutí
            if (pvPower > n_trigger_MPPT && nBattery_Power >= n_trigger_Changer) {
                sStatusText = "VYPNUTO - MPPT nabíjí bat (M:" + pvPower + "W, B:+" + nBattery_Power + "W)";
            } else if (pvPower <= n_trigger_MPPT && nBattery_Power >= 0) {
                sStatusText = "VYPNUTO - Nízká produkce (M:" + pvPower + "W, B:" + nBattery_Power + "W)";
            } else {
                sStatusText = "VYPNUTO - Pod triggerem (M:" + pvPower + "W, B:" + nBattery_Power + "W)";
            }
        }
    }

    // Vytvořit URL na základě hodnoty sTurn
    _url = fSendUrl(sIpAddress, nRelayNumber, sTurn);

    // Nastavit payload zprávy
    msg.payload = {
        _url_ch: _url,
        sTurn: sTurn + " CHANGER",
        nTurn: nTurn,
        pvPower: pvPower,
        nBattery_Power: nBattery_Power,
    };

    // Zobrazení stavu přímo pod nodem (viditelné v editoru)
    node.status({
        fill: nTurn === 1 ? "green" : "grey",
        shape: "dot",
        text: sStatusText
    });

    // Debug výpisy do konzole
    if (debug) {
        node.warn("=== COOLING CHANGER DEBUG ===");
        node.warn("MPPT (pvPower): " + pvPower + "W");
        node.warn("Baterie (nBattery_Power): " + nBattery_Power + "W");
        node.warn("Chlazení: " + sTurn);
        node.warn("Status: " + sStatusText);
        node.warn("URL: " + _url);
        node.warn("============================");
    }
} else {
    node.error("Globální funkce nebyly nalezeny. <- FORM CHLAZENI FVE -- CHANGER");
    node.status({
        fill: "red",
        shape: "ring",
        text: "Chyba: Globální funkce nenalezeny"
    });
}
return msg;

