//*****************************************************************************
//
// File Name        : N/A
// Title            : Cooling Control with Hysteresis
// Author           : http://www.prochazka.zde.cz
// Created          : 16-07-2024, 04:40
// Revised          : 14-12-2025, 12:00
// Version          : 1.2
// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Tento skript řídí zapínání/vypínání ventilátoru s hysterezí pro zabránění
// častého přepínání (fluktuace).
//
// ZAPNUTÍ VENTILÁTORU:
// - Musí přijít 3x po sobě požadavek na zapnutí (nTurn = true)
// - Pokud mezitím přijde požadavek na vypnutí, čítač se vynuluje
//
// VYPNUTÍ VENTILÁTORU:
// - Musí přijít 20x po sobě požadavek na vypnutí (nTurn = false)
// - Pokud mezitím přijde požadavek na zapnutí, čítač se vynuluje
//
// NASTAVENÍ:
// - nWaitLoop = 20 (kolik cyklů čekat pro vypnutí)
// - nWaitStartLoop = 3 (kolik cyklů čekat pro zapnutí)
// - debug = true/false (zapne/vypne debug zprávy)
//
// VSTUPNÍ DATA:
// - msg.payload._url_ch - URL pro ovládání relé
// - msg.payload.nTurn - požadavek na stav (true=zapnout, false=vypnout)
//
// VÝSTUPNÍ DATA:
// - msg.payload - URL které se odešle pouze při změně stavu
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2025 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = true;  // Nastavte na true pro zapnutí debug zpráv

// KONFIGURACE
const nWaitLoop = 20;       // Kolik cyklů čekat pro VYPNUTÍ
const nWaitStartLoop = 3;   // Kolik cyklů čekat pro ZAPNUTÍ

// Inicializace kontextových proměnných
let nCopyOnChange_url_ch = context.get('nCopyOnChange_url_ch') || "";
let nWaitLoopOff_ch = context.get('nWaitLoopOff_ch') || 0;      // Čítač pro vypnutí
let nWaitLoopOn_ch = context.get('nWaitLoopOn_ch') || 0;        // Čítač pro zapnutí
let bVentilatorState = context.get('bVentilatorState') || false; // Aktuální stav ventilátoru

// Načtení vstupních dat
const _url_ch = msg.payload && msg.payload._url_ch ? msg.payload._url_ch : "";
const nTurn = msg.payload && msg.payload.nTurn !== undefined ? msg.payload.nTurn : false;

let sStatusText = "";
let bSendCommand = false;

// Logika řízení ventilátoru
if (nTurn == true) {
    // Požadavek na ZAPNUTÍ
    nWaitLoopOn_ch += 1;
    nWaitLoopOff_ch = 0; // Vynulovat čítač vypnutí

    if (nWaitLoopOn_ch >= nWaitStartLoop) {
        // Dosaženo požadovaného počtu požadavků na zapnutí
        if (bVentilatorState == false) {
            // Ventilátor byl vypnutý, zapnout ho
            bVentilatorState = true;
            bSendCommand = true;
            context.set('nCopyOnChange_url_ch', _url_ch);
            sStatusText = "ZAPNUTO (" + nWaitLoopOn_ch + "/" + nWaitStartLoop + " požadavků)";
        } else {
            sStatusText = "ZAPNUTO (běží)";
        }
        nWaitLoopOn_ch = 0; // Vynulovat čítač
    } else {
        // Ještě nedosaženo požadovaného počtu
        sStatusText = "Čeká na zapnutí (" + nWaitLoopOn_ch + "/" + nWaitStartLoop + ")";
        if (bVentilatorState) {
            sStatusText += " - běží";
        } else {
            sStatusText += " - vypnuto";
        }
    }

} else {
    // Požadavek na VYPNUTÍ
    nWaitLoopOff_ch += 1;
    nWaitLoopOn_ch = 0; // Vynulovat čítač zapnutí

    if (nWaitLoopOff_ch >= nWaitLoop) {
        // Dosaženo požadovaného počtu požadavků na vypnutí
        if (bVentilatorState == true) {
            // Ventilátor byl zapnutý, vypnout ho
            bVentilatorState = false;
            bSendCommand = true;
            context.set('nCopyOnChange_url_ch', _url_ch);
            sStatusText = "VYPNUTO (" + nWaitLoopOff_ch + "/" + nWaitLoop + " požadavků)";
        } else {
            sStatusText = "VYPNUTO (stojí)";
        }
        nWaitLoopOff_ch = 0; // Vynulovat čítač
    } else {
        // Ještě nedosaženo požadovaného počtu
        sStatusText = "Čeká na vypnutí (" + nWaitLoopOff_ch + "/" + nWaitLoop + ")";
        if (bVentilatorState) {
            sStatusText += " - běží";
        } else {
            sStatusText += " - vypnuto";
        }
    }
}

// Uložit čítače do kontextu
context.set('nWaitLoopOff_ch', nWaitLoopOff_ch);
context.set('nWaitLoopOn_ch', nWaitLoopOn_ch);
context.set('bVentilatorState', bVentilatorState);

// Zobrazení stavu pod nodem
node.status({
    fill: bVentilatorState ? "green" : "grey",
    shape: "dot",
    text: sStatusText
});

// Debug výpisy
if (debug) {
    node.warn("=== VENTILÁTOR CONTROL DEBUG ===");
    node.warn("Požadavek (nTurn): " + (nTurn ? "ZAPNOUT" : "VYPNOUT"));
    node.warn("Stav ventilátoru: " + (bVentilatorState ? "BĚŽÍ" : "VYPNUTO"));
    node.warn("Čítač zapnutí: " + nWaitLoopOn_ch + "/" + nWaitStartLoop);
    node.warn("Čítač vypnutí: " + nWaitLoopOff_ch + "/" + nWaitLoop);
    node.warn("Odesílám příkaz: " + (bSendCommand ? "ANO" : "NE"));
    node.warn("URL: " + _url_ch);
    node.warn("================================");
}

// Odeslat zprávu pouze při změně stavu
if (bSendCommand) {
    msg.payload = _url_ch;
    return msg;
} else {
    return null; // Neposílat zprávu
}

//*****************************************************************************
//
// File Name        : N/A
// Title            : MPTT Cooling Control with Hysteresis
// Author           : http://www.prochazka.zde.cz
// Created          : 16-07-2024, 04:40
// Revised          : 14-12-2025, 12:45
// Version          : 1.2
// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Tento skript řídí zapínání/vypínání ventilátoru MPTT s hysterezí pro zabránění
// častého přepínání (fluktuace).
//
// ZAPNUTÍ VENTILÁTORU:
// - Musí přijít 3x po sobě požadavek na zapnutí (nTurn = true)
// - Pokud mezitím přijde požadavek na vypnutí, čítač se vynuluje
//
// VYPNUTÍ VENTILÁTORU:
// - Musí přijít 20x po sobě požadavek na vypnutí (nTurn = false)
// - Pokud mezitím přijde požadavek na zapnutí, čítač se vynuluje
//
// NASTAVENÍ:
// - nWaitLoop = 20 (kolik cyklů čekat pro vypnutí)
// - nWaitStartLoop = 2 (kolik cyklů čekat pro zapnutí)
// - debug = true/false (zapne/vypne debug zprávy)
//
// VSTUPNÍ DATA:
// - msg.payload._url_m - URL pro ovládání relé
// - msg.payload.nTurn - požadavek na stav (true=zapnout, false=vypnout)
//
// VÝSTUPNÍ DATA:
// - msg.payload - URL které se odešle pouze při změně stavu
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2025 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = true;  // Nastavte na true pro zapnutí debug zpráv

// KONFIGURACE
const nWaitLoop = 20;       // Kolik cyklů čekat pro VYPNUTÍ
const nWaitStartLoop = 2;   // Kolik cyklů čekat pro ZAPNUTÍ

// Inicializace kontextových proměnných
let nCopyOnChange_url_m = context.get('nCopyOnChange_url_m') || "";
let nWaitLoopOff_m = context.get('nWaitLoopOff_m') || 0;      // Čítač pro vypnutí
let nWaitLoopOn_m = context.get('nWaitLoopOn_m') || 0;        // Čítač pro zapnutí
let bVentilatorState = context.get('bVentilatorState_m') || false; // Aktuální stav ventilátoru

// Načtení vstupních dat
const _url_m = msg.payload && msg.payload._url_m ? msg.payload._url_m : "";
const nTurn = msg.payload && msg.payload.nTurn !== undefined ? msg.payload.nTurn : false;

let sStatusText = "";
let bSendCommand = false;

// Logika řízení ventilátoru
if (nTurn == true) {
    // Požadavek na ZAPNUTÍ
    nWaitLoopOn_m += 1;
    nWaitLoopOff_m = 0; // Vynulovat čítač vypnutí

    if (nWaitLoopOn_m >= nWaitStartLoop) {
        // Dosaženo požadovaného počtu požadavků na zapnutí
        if (bVentilatorState == false) {
            // Ventilátor byl vypnutý, zapnout ho
            bVentilatorState = true;
            bSendCommand = true;
            context.set('nCopyOnChange_url_m', _url_m);
            sStatusText = "ZAPNUTO (" + nWaitLoopOn_m + "/" + nWaitStartLoop + " požadavků)";
        } else {
            sStatusText = "ZAPNUTO (běží)";
        }
        nWaitLoopOn_m = 0; // Vynulovat čítač
    } else {
        // Ještě nedosaženo požadovaného počtu
        sStatusText = "Čeká na zapnutí (" + nWaitLoopOn_m + "/" + nWaitStartLoop + ")";
        if (bVentilatorState) {
            sStatusText += " - běží";
        } else {
            sStatusText += " - vypnuto";
        }
    }

} else {
    // Požadavek na VYPNUTÍ
    nWaitLoopOff_m += 1;
    nWaitLoopOn_m = 0; // Vynulovat čítač zapnutí

    if (nWaitLoopOff_m >= nWaitLoop) {
        // Dosaženo požadovaného počtu požadavků na vypnutí
        if (bVentilatorState == true) {
            // Ventilátor byl zapnutý, vypnout ho
            bVentilatorState = false;
            bSendCommand = true;
            context.set('nCopyOnChange_url_m', _url_m);
            sStatusText = "VYPNUTO (" + nWaitLoopOff_m + "/" + nWaitLoop + " požadavků)";
        } else {
            sStatusText = "VYPNUTO (stojí)";
        }
        nWaitLoopOff_m = 0; // Vynulovat čítač
    } else {
        // Ještě nedosaženo požadovaného počtu
        sStatusText = "Čeká na vypnutí (" + nWaitLoopOff_m + "/" + nWaitLoop + ")";
        if (bVentilatorState) {
            sStatusText += " - běží";
        } else {
            sStatusText += " - vypnuto";
        }
    }
}

// Uložit čítače do kontextu
context.set('nWaitLoopOff_m', nWaitLoopOff_m);
context.set('nWaitLoopOn_m', nWaitLoopOn_m);
context.set('bVentilatorState_m', bVentilatorState);

// Zobrazení stavu pod nodem
node.status({
    fill: bVentilatorState ? "green" : "grey",
    shape: "dot",
    text: sStatusText
});

// Debug výpisy
if (debug) {
    node.warn("=== VENTILÁTOR MPTT CONTROL DEBUG ===");
    node.warn("Požadavek (nTurn): " + (nTurn ? "ZAPNOUT" : "VYPNOUT"));
    node.warn("Stav ventilátoru: " + (bVentilatorState ? "BĚŽÍ" : "VYPNUTO"));
    node.warn("Čítač zapnutí: " + nWaitLoopOn_m + "/" + nWaitStartLoop);
    node.warn("Čítač vypnutí: " + nWaitLoopOff_m + "/" + nWaitLoop);
    node.warn("Odesílám příkaz: " + (bSendCommand ? "ANO" : "NE"));
    node.warn("URL: " + _url_m);
    node.warn("======================================");
}

// Odeslat zprávu pouze při změně stavu
if (bSendCommand) {
    msg.payload = _url_m;
    return msg;
} else {
    return null; // Neposílat zprávu
}

