// a zobrazuje aktuální fyzický stav obou ventilátorů.
//
// VSTUPNÍ DATA:
// - msg.statusCode - HTTP status code (musí být 200)
// - msg.responseUrl - URL requestu obsahující IP a stav (turn=on/off)
// - msg.payload - JSON odpověď ze zařízení
//
// VÝSTUPNÍ DATA:
// - msg.payload.indicator - identifikátor ventilátoru ('mptt-fan' nebo 'changer-fan')
// - msg.payload.status - stav ventilátoru ('on' nebo 'off')
// - msg.payload.topic - téma zprávy ('update-indicator')
//
// ROZPOZNÁNÍ ZAŘÍZENÍ:
// - IP 192.168.11.7 = MPTT ventilátor
// - IP 192.168.11.9 = CHANGER ventilátor
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2025 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = true;  // Nastavte na true pro zapnutí debug zpráv

// Kontrola statusCode
if (msg.statusCode !== 200) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Chyba: HTTP " + (msg.statusCode || "bez odpovědi")
    });
    return null; // Pokud není statusCode 200, vrátíme null a ukončíme zpracování
}

const response = JSON.parse(msg.payload);
let sURL = msg.responseUrl;

// Ruční zpracování URL pro získání IP adresy a hodnoty 'turn'
let ipAddress = sURL.split('/')[2];
let turnValue = sURL.includes('turn=on') ? 'on' : 'off';

let indicatorMsg = {};
let sStatusText = "";

// Debugging vstupních dat
if (debug) {
    node.warn("=== PROCESS RESPONSE DEBUG ===");
    node.warn("sURL: " + sURL);
    node.warn("ipAddress: " + ipAddress);
    node.warn("turnValue: " + turnValue);
}

// Inicializace nebo načtení kontextových proměnných pro oba ventilátory
let mpttFanStatus = context.get('mpttFanStatus') || 'unknown';
let changerFanStatus = context.get('changerFanStatus') || 'unknown';

// Aktualizace příslušného ventilátoru
if (ipAddress === '192.168.11.7') {
    mpttFanStatus = turnValue;
    context.set('mpttFanStatus', mpttFanStatus);
    indicatorMsg = { indicator: 'mptt-fan', status: turnValue, topic: 'update-indicator' };
} else if (ipAddress === '192.168.11.9') {
    changerFanStatus = turnValue;
    context.set('changerFanStatus', changerFanStatus);
    indicatorMsg = { indicator: 'changer-fan', status: turnValue, topic: 'update-indicator' };
}

// Sestavení textu pro status
let mpttText = mpttFanStatus === 'on' ? '🟢 MPTT' : (mpttFanStatus === 'off' ? '⚪ MPTT' : '⚫ MPTT');
let changerText = changerFanStatus === 'on' ? '🟢 CHANGER' : (changerFanStatus === 'off' ? '⚪ CHANGER' : '⚫ CHANGER');
sStatusText = mpttText + " | " + changerText;

// Určení barvy pro status (pokud alespoň jeden běží = zelená)
let statusFill = "grey";
if (mpttFanStatus === 'on' || changerFanStatus === 'on') {
    statusFill = "green";
}
if (mpttFanStatus === 'unknown' || changerFanStatus === 'unknown') {
    statusFill = "yellow";
}

// Zobrazení stavu obou ventilátorů pod nodem
node.status({
    fill: statusFill,
    shape: "dot",
    text: sStatusText
});

// Debug výpis
if (debug) {
    node.warn("MPTT Fan Status: " + mpttFanStatus);
    node.warn("CHANGER Fan Status: " + changerFanStatus);
    node.warn("Status Text: " + sStatusText);
    node.warn("=============================");
}

return { payload: indicatorMsg };

